  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B028",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks combine quantum control with unprecedented precision and have reshaped timekeeping and tests of fundamental physics. Their significance is both metrological and fundamental.",
        "attribution": "Katori and Ye made central, complementary contributions to the clock concept and its experimental realization. The field is broad, but their roles are especially clear.",
        "maturity": "The method has been developed and independently advanced over decades, with performance and applications established across laboratories.",
        "uncertainties": [
          "The eventual Nobel boundary between the optical lattice clock and related optical clock developments would need careful definition."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how fragile quantum information can, in principle, be protected from noise. This is a deep conceptual advance with major consequences for quantum physics and computation.",
        "attribution": "Shor and Steane independently established influential early codes; Kitaev developed the topological route to fault tolerance. These are distinct, recognizable contributions, though the wider field has many essential contributors.",
        "maturity": "The theory is well established and has guided sustained experimental progress. Large scale fault tolerant computation remains unrealized, but the central principles are mature.",
        "uncertainties": [
          "A prize would need to distinguish the fundamental theory from later engineering and implementation advances."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B031",
      "proposed_laureates": [
        "Michael Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "The Aharonov–Bohm effect and Berry phase reveal that quantum phases carry physical consequences beyond local force measurements. Their reach across quantum mechanics and many areas of physics is exceptionally broad.",
        "attribution": "Aharonov, with Bohm, established the effect of electromagnetic potentials on quantum phase; Berry identified the general geometric phase in adiabatic evolution. The two contributions are related but distinct.",
        "maturity": "The concepts are firmly established and have been observed and applied in many physical settings.",
        "uncertainties": [
          "The ballot combines two major developments, and any award would need to decide whether they form one coherent discovery."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B010",
      "proposed_laureates": [
        "Alexander A. Belavin",
        "Alexander B. Zamolodchikov",
        "Alexander M. Polyakov"
      ],
      "assessment": {
        "nobel_worthiness": "Two dimensional conformal field theory supplied exact tools for critical phenomena and transformed the study of statistical systems and quantum field theory. Its intellectual influence is unusually deep.",
        "attribution": "The Belavin–Polyakov–Zamolodchikov work is a landmark collective contribution by these three theorists, with a clear and historically recognizable attribution.",
        "maturity": "The framework has been developed and used extensively over several decades; its importance does not depend on a single experimental confirmation.",
        "uncertainties": [
          "The Nobel Committee may weigh the mainly theoretical character of this achievement differently from experimentally established discoveries."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Christopher Jarzynski",
        "Gavin E. Crooks",
        "Udo Seifert"
      ],
      "assessment": {
        "nobel_worthiness": "Fluctuation relations extend thermodynamic reasoning to small systems far from equilibrium, where fluctuations are unavoidable. They have clarified the connection between microscopic dynamics and macroscopic irreversibility.",
        "attribution": "Jarzynski and Crooks established influential nonequilibrium work relations, while Seifert developed a broad stochastic thermodynamics framework. Earlier and parallel work, including that of Evans, is important to a full history.",
        "maturity": "The relations have been tested in diverse experimental systems and are now standard tools in nonequilibrium physics.",
        "uncertainties": [
          "The field's development is distributed across several contributors, making a sharply bounded laureate group difficult."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Alan H. Guth",
        "Andrei Linde",
        "Viatcheslav Mukhanov"
      ],
      "assessment": {
        "nobel_worthiness": "Inflation offers a powerful account of early-universe expansion and a mechanism for the origin of cosmic structure. Its explanatory scope makes it a major theoretical achievement.",
        "attribution": "Guth introduced the inflationary idea; Linde developed influential models; Mukhanov, with Chibisov, derived the quantum origin of primordial perturbations. The proposed names capture central but not exhaustive contributions.",
        "maturity": "The framework is mature and tied to precision cosmological observations, but no unique inflationary model has been established.",
        "uncertainties": [
          "Inflation remains an inference rather than a directly verified account of the earliest universe.",
          "The observations strongly constrain models but do not uniquely establish inflation or its proposed quantum mechanism."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B016",
      "proposed_laureates": [
        "Christian J. Bordé",
        "David E. Pritchard",
        "Mark A. Kasevich"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry uses matter-wave coherence for exceptionally sensitive measurements of acceleration, rotation, and fundamental quantities. It is a powerful demonstration of quantum mechanics at the scale of controlled atoms.",
        "attribution": "Bordé established important early atom interferometry methods, Pritchard advanced atom-based interferometric measurements, and Kasevich helped develop precision light-pulse instruments. The field also has many important contributors.",
        "maturity": "The method has been demonstrated and refined across laboratories, with a substantial record of precision measurements.",
        "uncertainties": [
          "The proposed group may not capture the full international history of the technique.",
          "Some of the field's strongest practical applications are still developing."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B015",
      "proposed_laureates": [
        "David DeMille",
        "John M. Doyle",
        "Michael R. Tarbutt"
      ],
      "assessment": {
        "nobel_worthiness": "Laser cooling and trapping of molecules opened new experimental access to complex quantum systems, precision tests, and controlled ultracold chemistry. It is a major advance in atomic and molecular physics.",
        "attribution": "DeMille and Doyle were central to early strategies and demonstrations for controlling cold molecules; Tarbutt made key contributions to direct laser cooling and trapping. Their work represents distinct stages of the advance.",
        "maturity": "The experimental achievement is well established and has enabled a growing body of research, though the field continues to develop.",
        "uncertainties": [
          "The distinction between this achievement and broader ultracold molecule control is not perfectly sharp.",
          "The long term fundamental reach of the platform is still being established."
        ]
      }
    }
  ]
}
